def eulerian_num(n, m):
    if m >= n or n == 0:
        return 0
    if m == 0:
        return 1
    res = 0
    for i in range(m + 1):
        if i == 0:
            res += pow(-1, i) * (pow(n - i, m) / (pow(n - i, 0)))
        else:
            res += pow(-1, i) * (pow(n - i, m) / (pow(n - i, i)))
    return int(res)

