def lps(s):
    """
    Finds the length of the longest palindromic subsequence in the given string.
    """
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # Strings of length 1 and 2
    for i in range(n):
        dp[i][i] = 1
    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = 2
        else:
            dp[i][i+1] = 1

    # Length 3 and above
    for cl in range(3, n+1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])

    return max([max(row) for row in dp])

# Test cases
